// Inductive step visualization
// Two-argument size fixes the output box at 320 x 200
size(320,200);
int k = 3;
pair points[] = { (1,1), (2,4), (3,9), (4,16) };
for (int i = 0; i <= k; ++i) {
  dot(points[i], black+3pt);
  if (i < k) draw(points[i]--points[i+1], blue);
}
label("P(1)", (1,1), SW);
label("P(2)", (2,4), SE);
label("\\ldots", (3,9), N);
label("P(k)", (k, k*k), NE);
label("P(k+1)", (k+1, (k+1)*(k+1)), N);

